import{_ as d,C as e,o as n,c as l,E as a,a7 as s}from"./chunks/framework.FWlv_suP.js";const g=JSON.parse('{"title":"Flowra Data Deletion","description":"Instructions for deleting data associated with the Flowra application.","frontmatter":{"title":"Flowra Data Deletion","description":"Instructions for deleting data associated with the Flowra application."},"headers":[],"relativePath":"apps/flowra/data-deletion.md","filePath":"apps/flowra/data-deletion.md"}'),p={name:"apps/flowra/data-deletion.md"};function c(h,t,u,f,b,m){const o=e("AppBreadcrumbs"),r=e("AppSubnav"),i=e("CopyStandaloneUrl");return n(),l("div",null,[a(o,{"app-id":"flowra",current:"Data Deletion"}),a(r,{"app-id":"flowra"}),a(i,{path:"/data-deletion/flowra",label:"Copy standalone data-deletion URL","copied-label":"Data-deletion URL copied","document-name":"Flowra data-deletion page"}),t[0]||(t[0]=s('<h1 id="delete-flowra-data" tabindex="-1">Delete Flowra Data <a class="header-anchor" href="#delete-flowra-data" aria-label="Permalink to &quot;Delete Flowra Data&quot;">​</a></h1><p>Flowra has no online account or developer-operated cloud database. Its health records, profiles, predictions, and settings are stored locally.</p><h2 id="delete-android-app-data" tabindex="-1">Delete Android app data <a class="header-anchor" href="#delete-android-app-data" aria-label="Permalink to &quot;Delete Android app data&quot;">​</a></h2><p>Use either Android option:</p><ol><li>Open <strong>Settings → Apps → Flowra → Storage</strong> and select <strong>Clear storage</strong> or <strong>Clear data</strong>; or</li><li>Uninstall Flowra.</li></ol><p>The exact labels vary by Android version and manufacturer. These actions remove Flowra&#39;s private SQLite database, settings, local biometric credential wrapper, and other app-private files. Android Keystore material associated with the app is managed by Android when app data is cleared or the app is removed.</p><h2 id="delete-browser-data" tabindex="-1">Delete browser data <a class="header-anchor" href="#delete-browser-data" aria-label="Permalink to &quot;Delete browser data&quot;">​</a></h2><p>For the browser version, clear site data for the Flowra web origin using your browser&#39;s privacy or site-storage settings. This removes the encrypted IndexedDB records and their local encryption key. Clearing only cookies may not remove IndexedDB, so select the option that clears all site data or storage.</p><h2 id="delete-exported-files-and-backups" tabindex="-1">Delete exported files and backups <a class="header-anchor" href="#delete-exported-files-and-backups" aria-label="Permalink to &quot;Delete exported files and backups&quot;">​</a></h2><p>Clearing app or browser data does not delete CSV exports, printed or saved PDF reports, or <code>.flowra</code> backup files. Delete each file separately from Documents, Downloads, other device folders, and any messaging, backup, or storage provider to which you copied or shared it.</p><h2 id="notifications" tabindex="-1">Notifications <a class="header-anchor" href="#notifications" aria-label="Permalink to &quot;Notifications&quot;">​</a></h2><p>Clearing app data or uninstalling the Android app removes its scheduled local notifications. You can also disable reminders inside Flowra or revoke its notification permission in Android settings.</p><p>Because the developer does not hold Flowra account or health data, no email request is needed to delete data stored by the app.</p>',13))])}const _=d(p,[["render",c]]);export{g as __pageData,_ as default};
